-- مكتبة الوجبات: كل الوصفات كوجبات يختار منها المتدرب في «كل الوجبات» + migration 030 (عمود is_library وتسمية سجل الأكل).
-- يُشغَّل في Neon ← SQL Editor في محرر فاضي، بعد ملف library-meals (029). تُضاف المكتبة مرة، وتُحدَّث لو انشغّل مرتين.
BEGIN;
DO $g$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM schema_migrations WHERE name = '030_meal_library_plan.sql') THEN
    EXECUTE $mig$-- =====================================================================
-- مكتبة الوجبات: جدول خاص (is_library) يحمل كل الوصفات كوجبات ليختار منها المتدرب في «كل الوجبات».
-- لا يظهر ضمن القوالب المقترحة ولا قائمة إسناد الجداول. وتسجيل وجبة قالب/مكتبة يحفظ اسم الوجبة فقط.
-- =====================================================================
ALTER TABLE nutrition_plans ADD COLUMN is_library boolean NOT NULL DEFAULT false;

CREATE OR REPLACE FUNCTION app.log_food(p_order_no text, p_date date, p_kind text, p_meal uuid,
                                        p_name text, p_protein numeric, p_carbs numeric, p_fat numeric) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  u text := app.require_user();
  v_order uuid;
  today date := (now() AT TIME ZONE 'Asia/Riyadh')::date;
  v_name text; v_tpl boolean; v_p numeric; v_c numeric; v_f numeric; v_kind text := p_kind;
  v_id bigint;
BEGIN
  SELECT id INTO v_order FROM orders WHERE order_no = p_order_no AND user_id = u;
  IF NOT FOUND OR NOT app.order_entitled(v_order) THEN RAISE EXCEPTION 'الطلب غير موجود.' USING ERRCODE = 'P0001'; END IF;
  IF p_date IS NULL OR p_date > today OR p_date < today - 60 THEN RAISE EXCEPTION 'التاريخ غير صحيح.' USING ERRCODE = 'P0001'; END IF;
  IF p_meal IS NOT NULL THEN
    SELECT m.title, m.kind, (p.order_id IS NULL), coalesce(sum(i.protein), 0), coalesce(sum(i.carbs), 0), coalesce(sum(i.fat), 0)
      INTO v_name, v_kind, v_tpl, v_p, v_c, v_f
      FROM plan_meals m JOIN nutrition_plans p ON p.id = m.plan_id LEFT JOIN plan_items i ON i.meal_id = m.id
     WHERE m.id = p_meal AND (p.order_id = v_order OR p.order_id IS NULL) AND NOT p.archived
     GROUP BY m.id, p.order_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'الوجبة غير موجودة.' USING ERRCODE = 'P0001'; END IF;
    -- وجبة من مكتبة الوجبات (قالب): الاسم بس؛ من جدول المتدرب: «الجدول — الوجبة»
    IF NOT v_tpl THEN v_name := (SELECT name FROM nutrition_plans WHERE id = app.meal_plan(p_meal)) || ' — ' || v_name; END IF;
    v_kind := coalesce(p_kind, v_kind);
  ELSE
    v_name := nullif(trim(coalesce(p_name, '')), '');
    IF v_name IS NULL THEN RAISE EXCEPTION 'اكتب اسم الأكلة.' USING ERRCODE = 'P0001'; END IF;
    v_p := coalesce(p_protein, 0); v_c := coalesce(p_carbs, 0); v_f := coalesce(p_fat, 0);
    IF v_p < 0 OR v_c < 0 OR v_f < 0 OR v_p > 500 OR v_c > 500 OR v_f > 300 THEN
      RAISE EXCEPTION 'أرقام الماكروز غير منطقية.' USING ERRCODE = 'P0001';
    END IF;
    IF v_p + v_c + v_f = 0 THEN RAISE EXCEPTION 'اكتب البروتين أو الكارب أو الدهون.' USING ERRCODE = 'P0001'; END IF;
  END IF;
  IF v_kind NOT IN ('breakfast', 'lunch', 'dinner', 'snack') THEN RAISE EXCEPTION 'اختر الوجبة.' USING ERRCODE = 'P0001'; END IF;
  IF (SELECT count(*) FROM food_logs WHERE user_id = u AND log_date = p_date) >= 30 THEN
    RAISE EXCEPTION 'وصلت الحد الأعلى لتسجيلات اليوم.' USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO food_logs (user_id, order_id, log_date, kind, meal_id, name, protein, carbs, fat)
  VALUES (u, v_order, p_date, v_kind, p_meal, left(v_name, 160), round(v_p, 1), round(v_c, 1), round(v_f, 1))
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;
$mig$;
    INSERT INTO schema_migrations (name) VALUES ('030_meal_library_plan.sql');
  END IF;
END $g$;
DO $do$
DECLARE
  d jsonb := $rt$[{"name":"مكتبة الوجبات","notes":"كل الوصفات كوجبات منفردة (فطور وغداء وسناك) ليختار منها المتدرب في «كل الوجبات». مو جدول يومي، فلا تُسند لمتدرب. 60 وجبة.","meals":[{"kind":"breakfast","title":"عجة البيض مع الجبن والخضار","method":"المكونات:\n• 4 بياض بيض + بيضة كاملة\n• 30غ جبن قريش أو جبن قليل الدسم\n• نص كوب فلفل رومي مع سبانخ\n• شريحة توست حبوب كاملة\n\nالطريقة:\n1. سخّن مقلاة غير لاصقة على نار متوسطة.\n2. اخفق البيض مع رشة ملح وفلفل.\n3. حط الفلفل الرومي والسبانخ بالمقلاة وقلّبهم دقيقة.\n4. اسكب خليط البيض فوق الخضار واتركه يتماسك.\n5. حط الجبن القريش وطوّي العجة بهدوء.\n6. قدّمها مع توست الحبوب الكاملة.","items":[{"food":"عجة البيض مع الجبن والخضار","portion":"وجبة كاملة","protein":31,"carbs":28,"fat":8}]},{"kind":"breakfast","title":"ساندوتش جبن حلوم مشوي","method":"المكونات:\n• 100غ جبن حلوم المراعي قليل الدسم\n• ساندوتش لوزين 50غ\n• جرجير\n\nالطريقة:\n1. نقطّع الحلوم شرائح.\n2. نسخّن المقلاة بقطرة زيت زيتون، ونحط الحلوم على نار هادية حوالي 3 دقايق لكل جهة، ونقلّبه لين يصير ذهبي.\n3. نضيف الجرجير، وبعدها نشيل الحلوم.\n4. نحمّص الساندوتش بنفس المقلاة شوي لين يصير ذهبي ومقرمش.\n5. نحشي الساندوتش بالحلوم والجرجير، وبالعافية.","items":[{"food":"ساندوتش جبن حلوم مشوي","portion":"وجبة كاملة","protein":32,"carbs":27,"fat":20}]},{"kind":"breakfast","title":"شوفان بالبروتين والمكسرات","method":"المكونات:\n• 40غ شوفان\n• 1 سكوب واي بروتين (Whey)\n• 1 ملعقة صغيرة زبدة لوز أو فول سوداني\n• نص كوب حليب لوز غير محلّى\n\nالطريقة:\n1. بقدر صغير نسخّن الحليب ونضيف الشوفان.\n2. نطبخه على نار هادية 5 دقايق لين يثقل.\n3. نرفعه عن النار ونتركه يبرد شوي، وبعدها نضيف البروتين ونحرّك زين.\n4. نزيّنه بزبدة الفول السوداني والمكسرات.","items":[{"food":"شوفان بالبروتين والمكسرات","portion":"وجبة كاملة","protein":30,"carbs":31,"fat":8}]},{"kind":"breakfast","title":"سموثي البروتين بالموز وزبدة الفول السوداني","method":"المكونات:\n• 1 سكوب واي بروتين (Whey)\n• نص موزة\n• 1 ملعقة صغيرة زبدة فول سوداني\n• 200مل حليب لوز غير محلّى\n• 30غ شوفان مطحون\n\nالطريقة:\n1. نحط كل المكونات بالخلاط.\n2. نخلطها لين يصير السموثي ناعم وكريمي.\n3. نسكبه بكوب ونشربه بارد.","items":[{"food":"سموثي البروتين بالموز وزبدة الفول السوداني","portion":"وجبة كاملة","protein":30,"carbs":38.6,"fat":9.2}]},{"kind":"breakfast","title":"زبادي يوناني مع مكسرات وفواكه","method":"المكونات:\n• 200غ زبادي يوناني خالي الدسم\n• 15غ مكسرات (لوز أو جوز)\n• 1 ملعقة صغيرة عسل\n• 50غ توت مشكّل\n\nالطريقة:\n1. نحط الزبادي بوعاء.\n2. نضيف المكسرات المفرومة والتوت.\n3. نزيّنه بالعسل ونقدّمه بارد.\n\nالألياف: 3.1غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA.","items":[{"food":"زبادي يوناني مع مكسرات وفواكه","portion":"وجبة كاملة","protein":24,"carbs":23.5,"fat":8.4}]},{"kind":"breakfast","title":"بان كيك البروتين بالشوفان","method":"المكونات:\n• 50غ شوفان مطحون\n• 1 سكوب واي بروتين (Whey)\n• 4 بياض بيض\n• نص ملعقة صغيرة قرفة\n• 120مل حليب لوز غير محلّى\n• نص ملعقة صغيرة زبدة فول سوداني (للتزيين)\n\nالطريقة:\n1. نخلط كل المكونات بوعاء لين يصير الخليط متجانس.\n2. نسخّن مقلاة غير لاصقة ونمسحها بقليل زيت.\n3. نسكب الخليط دوائر صغيرة ونتركها لين تطلع الفقاقيع، وبعدها نقلبها.\n4. نقدّمها مع زبدة الفول السوداني أو شوية عسل.","items":[{"food":"بان كيك البروتين بالشوفان","portion":"وجبة كاملة","protein":38,"carbs":45,"fat":9}]},{"kind":"breakfast","title":"توست البيض والأفوكادو مع جبن القريش","method":"المكونات:\n• شريحة توست حبوب كاملة\n• 2 بياض بيض + بيضة كاملة\n• 50غ جبن قريش\n• 30غ أفوكادو\n• رشة ملح وفلفل أسود\n\nالطريقة:\n1. ندهن التوست بالأفوكادو المهروس.\n2. نوزّع الجبن القريش فوقه.\n3. نضيف شرايح البيض المسلوق ونتبّل بالملح والفلفل.\n\nالألياف: 3.9غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA.","items":[{"food":"توست البيض والأفوكادو مع جبن القريش","portion":"وجبة كاملة","protein":23.3,"carbs":19.6,"fat":12.1}]},{"kind":"breakfast","title":"ساندويتش التونة بالأفوكادو على خبز الحبوب الكاملة","method":"المكونات:\n• 140غ تونة معلّبة بالماء، مصفّاة زين\n• 50غ أفوكادو مهروس\n• شريحة خبز حبوب كاملة\n• نص ملعقة صغيرة عصير ليمون\n• رشة ملح وفلفل أسود\n\nالطريقة:\n1. نخلط التونة مع الأفوكادو والليمون والملح والفلفل.\n2. نحط الخليط فوق شريحة الخبز.\n3. نقدّمه مع شرايح خيار أو طماطم على الجنب.\n\nالألياف: 5.3غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. عصير الليمون غير محسوب.","items":[{"food":"ساندويتش التونة بالأفوكادو على خبز الحبوب الكاملة","portion":"وجبة كاملة","protein":32.2,"carbs":17.9,"fat":9.9}]},{"kind":"breakfast","title":"بيض مخفوق مع الجبن والديك الرومي","method":"المكونات:\n• 2 بيضة كاملة\n• 3 بياض بيض\n• 100غ شرايح ديك رومي مدخّن قليل الدهون\n• 30غ جبن قريش أو جبن قليل الدسم\n• 1 ملعقة صغيرة زيت زيتون\n• رشة ملح وفلفل أسود\n\nالطريقة:\n1. نسخّن زيت الزيتون بالمقلاة.\n2. نخفق البيض ونضيفه للمقلاة مع شرايح الديك الرومي.\n3. نضيف الجبن بالآخر ونتركه يذوب شوي، ونقدّمه سخن.\n\nالألياف: 0غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA.","items":[{"food":"بيض مخفوق مع الجبن والديك الرومي","portion":"وجبة كاملة","protein":56.6,"carbs":2.8,"fat":17.5}]},{"kind":"lunch","title":"دجاج مشوي مع الأرز البني والخضار","method":"المكونات:\n• 150غ صدر دجاج مشوي\n• 150غ أرز بني مطبوخ\n• 90غ بروكلي\n• 30غ جزر\n• 30غ فلفل رومي\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• بهارات (ملح، فلفل، كمون)\n\nالطريقة:\n1. نتبّل الدجاج بالملح والفلفل والكمون، ونشويه لين ينضج.\n2. بمقلاة نسخّن زيت الزيتون ونضيف البروكلي والجزر والفلفل ونقلّبها لين تنضج.\n3. نقدّم الدجاج مع الأرز والخضار.\n\nالألياف: 6.8غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. البهارات غير محسوبة.","items":[{"food":"دجاج مشوي مع الأرز البني والخضار","portion":"وجبة كاملة","protein":53.3,"carbs":49.6,"fat":12.4}]},{"kind":"lunch","title":"سمك السلمون المشوي مع البطاطا الحلوة","method":"المكونات:\n• 150غ فيليه سلمون\n• نص كوب بطاطا حلوة مشوية\n• 1 ملعقة صغيرة زيت زيتون\n• نص ملعقة صغيرة بهارات (بابريكا، ملح، فلفل)\n\nالطريقة:\n1. نتبّل السلمون بالملح والبابريكا ونشويه بالفرن أو بالمقلاة لين ينضج، تقريباً 15–20 دقيقة.\n2. نشوي البطاطا الحلوة بزيت الزيتون بالفرن لين تصير ذهبية.","items":[{"food":"سمك السلمون المشوي مع البطاطا الحلوة","portion":"وجبة كاملة","protein":35,"carbs":21,"fat":25}]},{"kind":"lunch","title":"ستيك لحم بالفطر مع رز","method":"المكونات:\n• 200غ ستيك برازيلي\n• 100غ رز أبيض مطبوخ\n• فطر بني\n• 1 ملعقة صغيرة زيت زيتون\n• رشة ملح وفلفل أسود وبودرة ثوم\n\nالطريقة:\n1. نسخّن المقلاة على حرارة عالية، ونحط الستيك من جهة الدهن أول دقيقة لين يتحمّر.\n2. بعدها نحطه كامل على المقلاة على نار متوسطة، 3 دقايق لكل جهة إذا نبيه Medium Well.\n3. نضيف الفطر ونقلّبه لين ينضج اللحم.\n4. نقدّمه مع الرز.","items":[{"food":"ستيك لحم بالفطر مع رز","portion":"وجبة كاملة","protein":54,"carbs":27,"fat":14}]},{"kind":"lunch","title":"معكرونة القمح الكامل مع الدجاج والصوص الأحمر","method":"المكونات:\n• 150غ صدور دجاج متبّلة ببهارات الكيجن\n• 80غ معكرونة قمح كامل مطبوخة\n• نص كوب صلصة طماطم طبيعية\n• 1 ملعقة صغيرة زيت زيتون\n• 1 ملعقة صغيرة جبن بارميزان مبشور\n\nالطريقة:\n1. نسخّن زيت الزيتون بالمقلاة، ونضيف الدجاج ونقلّبه شوي.\n2. نضيف صلصة الطماطم ونتركها على نار هادية 5 دقايق لين تتسبّك.\n3. نخلط المعكرونة مع الصوص والدجاج، ونرش البارميزان.","items":[{"food":"معكرونة القمح الكامل مع الدجاج والصوص الأحمر","portion":"وجبة كاملة","protein":53,"carbs":34,"fat":11}]},{"kind":"lunch","title":"أرز بالكاري مع الدجاج والخضار","method":"المكونات:\n• 200غ صدور دجاج\n• 75غ جزر\n• 75غ فلفل رومي\n• 50غ بازيلاء\n• 1 بصلة متوسطة\n• 2 فص ثوم\n• بهارات (كاري، كركم، كمون وغيرها)\n• 1 ملعقة كبيرة زيت\n• 3/4 كوب أرز مطبوخ\n\nالطريقة:\n1. قطّع صدور الدجاج مكعبات. (اختياري: انقعها بالزبادي مع الملح والفلفل 30 دقيقة).\n2. سخّن الزيت والزبدة بقدر عميق على نار عالية.\n3. أضف الدجاج وقلّبه 8–10 دقايق لين يتحمّر من كل الجهات.\n4. أضف البصل والثوم والزنجبيل وقلّب دقيقة.\n5. أضف البهارات (كاري، كركم، بابريكا، كمون، ملح، فلفل أسود) وقلّب زين.\n6. أضف الخضار (جزر، فلفل رومي، بازيلاء) وقلّب الخليط.\n7. أضف معجون الطماطم ومرق الدجاج. تقدر تضيف حليب جوز الهند للصوص الكريمي.\n8. خفّف النار وغطّ القدر واتركه يطبخ بهدوء 15–20 دقيقة لين تنضج الخضار والدجاج.\n9. عدّل الملح والفلفل، وأضف فلفل حار إذا تبي.\n10. قدّمه سخن مع الأرز، ومزيّن بكزبرة طازجة أو نعناع.","items":[{"food":"أرز بالكاري مع الدجاج والخضار","portion":"وجبة كاملة","protein":67,"carbs":51,"fat":25}]},{"kind":"lunch","title":"ستيك اللحم مع البطاطا والخضار","method":"المكونات:\n• 150غ ستيك لحم بقري قليل الدهن\n• 150غ بطاطا مشوية أو مسلوقة\n• كوب خضار سوتيه (فلفل، كوسا، بروكلي)\n• 1 ملعقة صغيرة زيت زيتون\n• ملح، فلفل، أعشاب مجففة\n\nالطريقة:\n1. نتبّل الستيك بالملح والفلفل ونشويه على نار متوسطة لين ينضج على ذوقك.\n2. نطبخ الخضار بمقلاة مع زيت الزيتون لين تصير طرية.\n3. نقدّم الستيك مع البطاطا والخضار.","items":[{"food":"ستيك اللحم مع البطاطا والخضار","portion":"وجبة كاملة","protein":44,"carbs":32,"fat":20}]},{"kind":"lunch","title":"دجاج بالكاجو مع الأرز البني والخضار","method":"المكونات:\n• 150غ صدر دجاج مقطّع (وزنه بعد الطبخ)\n• 150غ أرز بني مطبوخ\n• 10غ كاجو محمّص\n• 40غ فلفل ألوان\n• 30غ بصل\n• 45غ بروكلي أو كوسة\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• فص ثوم وقطعة زنجبيل مبشور\n• نص ملعقة صغيرة صوص صويا قليل الصوديوم\n\nالطريقة:\n1. نسلق الأرز البني بماء لين ينضج، ونصفّيه.\n2. بمقلاة غير لاصقة نسخّن زيت الزيتون ونضيف الدجاج والفلفل والبصل والبروكلي، ونقلّب على نار متوسطة لين يتحمّر الدجاج وتنضج الخضار وتبقى مقرمشة (8–10 دقايق).\n3. نضيف الثوم والزنجبيل دقيقة، وبعدها صوص الصويا ونقلّب.\n4. نطفي النار ونضيف الكاجو بالآخر عشان يبقى مقرمش، ونقدّمها فوق الأرز البني.\n\nالألياف: 5.6غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. الثوم والزنجبيل وصوص الصويا غير محسوبة.","items":[{"food":"دجاج بالكاجو مع الأرز البني والخضار","portion":"وجبة كاملة","protein":54.2,"carbs":49.9,"fat":16.6}]},{"kind":"lunch","title":"روبيان مشوي مع الكينوا والخضار","method":"المكونات:\n• 150غ روبيان (جمبري) مشوي\n• 150غ كينوا مطبوخة\n• نص كوب فلفل رومي مشوي\n• 1 ملعقة صغيرة زيت زيتون\n• نص ملعقة صغيرة عصير ليمون\n\nالطريقة:\n1. نغسل الروبيان وننشّفه زين، ونتبّله بملح وفلفل أسود وعصير ليمون وفص ثوم مهروس ورشة بابريكا أو كمون (اختياري)، ونتركه 10–15 دقيقة.\n2. الكينوا نطبخها بماء مملّح خفيف (جزء كينوا وجزئين ماء) لين تشرب الماء وتلين، ونتركها تبرد شوي.\n3. نشوي الروبيان بمقلاة شواء أو غير لاصقة مع ملعقة صغيرة زيت زيتون على نار متوسطة عالية، 2–3 دقايق لكل جهة لين يصير زهري ومتماسك.\n4. نشوي الفلفل الرومي بنفس المقلاة أو بالفرن لين ياخذ لون خفيف، ونقطّعه ونخلطه مع الكينوا.\n5. نتبّل الكينوا والفلفل بملح خفيف وفلفل أسود وعصير ليمون زيادة ورشة زيت زيتون إذا احتاج، ونقدّم الروبيان فوقها.","items":[{"food":"روبيان مشوي مع الكينوا والخضار","portion":"وجبة كاملة","protein":38,"carbs":43,"fat":10}]},{"kind":"lunch","title":"معكرونة الدجاج بالكريمة","method":"المكونات:\n• 150غ صدر دجاج مشوي ومقطّع\n• 80غ معكرونة قمح كامل مطبوخة\n• نص كوب حليب قليل الدسم\n• 1 ملعقة صغيرة زيت زيتون\n• 1 ملعقة صغيرة دقيق قمح كامل\n• نص ملعقة صغيرة ثوم بودرة وملح وفلفل\n\nالطريقة:\n1. نسلق المعكرونة بماء مملّح خفيف ونصفّيها، ونحتفظ بشوية من ماء السلق نستخدمها إذا الصوص احتاج تخفيف.\n2. بمقلاة نسخّن ملعقة زيت زيتون على نار متوسطة، ونضيف الدقيق ونحرّكه لين ياخذ لون ذهبي خفيف وريحة محمّصة.\n3. نضيف الحليب بالتدريج مع التحريك المستمر لين يتكاثف ويصير مثل صوص كريمي خفيف، وبعدها نضيف الثوم البودرة والملح والفلفل. وممكن رشة جوزة الطيب أو أوريجانو لطعم ألذ.\n4. نضيف الدجاج والمعكرونة للصوص ونحرّك على نار هادية دقيقتين لين يتغلّفون زين. وإذا صار القوام سميك نضيف شوي من ماء سلق المعكرونة.\n5. نقدّمها سخنة، وممكن نزيّنها ببقدونس مفروم أو فلفل أسود طازج.\n\nالألياف: 1.4غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA. ملعقة الدقيق غير محسوبة.","items":[{"food":"معكرونة الدجاج بالكريمة","portion":"وجبة كاملة","protein":55.3,"carbs":30.8,"fat":12.3}]},{"kind":"snack","title":"براونيز البروتين بالشوكولاتة","method":"المكونات:\n• 1 سكوب واي بروتين نكهة شوكولاتة (30غ)\n• نص كوب زبادي يوناني قليل الدسم (120غ)\n• ربع كوب حليب خالي الدسم (60غ)\n• 2 ملعقة كبيرة عسل (42غ)\n• بيضة (50غ)\n• 20غ شوكولاتة داكنة (70–85%) مذوّبة\n• نص ملعقة صغيرة بيكنج باودر\n• نص ملعقة صغيرة فانيلا\n\nالطريقة:\n1. نسخّن الفرن على 180°م ونبطّن صينية صغيرة بورق زبدة.\n2. نذوّب الشوكولاتة الداكنة بالمايكرويف 20–30 ثانية.\n3. بوعاء نخفق البيضة، ونضيف العسل والزبادي والحليب والفانيلا والشوكولاتة المذوّبة.\n4. نضيف البروتين والبيكنج باودر ونخلط لين يصير الخليط ناعم.\n5. نسكب الخليط بالصينية ونخبزه 15–18 دقيقة لين تتماسك الحواف ويبقى الوسط شوي رطب.\n6. نتركها تبرد وبعدها نقطّعها 6 مربعات.\n\nالألياف: 0.4غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA، والواي من ملف تغذية المدربة (سكوب = 25غ بروتين، 3 كارب، 2 دهون). القيم لقطعة وحدة. بدّلنا بودرة الكاكاو والستيفيا وحليب اللوز بمكونات معروفة القيم.","items":[{"food":"براونيز البروتين بالشوكولاتة","portion":"قطعة (1/6 من الصينية)","protein":7.8,"carbs":9.1,"fat":2.9}]},{"kind":"snack","title":"تشيز كيك البروتين بالفراولة","method":"المكونات:\n• 60غ جبن قريش\n• نص سكوب واي بروتين نكهة فانيلا (15غ)\n• 60غ زبادي يوناني قليل الدسم\n• 2 حبة فراولة (24غ)\n• نص ملعقة صغيرة فانيلا\n• محلّي ستيفيا حسب الرغبة\n\nالطريقة:\n1. نخلط كل المكونات ما عدا الفراولة بالخلاط لين نحصل على قوام كريمي.\n2. نسكب الخليط بكوب ونقدّمه مع الفراولة فوق.\n3. نبرّده بالثلاجة 30 دقيقة عشان يصير ألذ.\n\nالألياف: 0.5غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA، والواي من ملف تغذية المدربة (سكوب = 25غ بروتين، 3 كارب، 2 دهون). الفانيلا والستيفيا بدون سعرات تُذكر.","items":[{"food":"تشيز كيك البروتين بالفراولة","portion":"كوب","protein":25,"carbs":8.6,"fat":3.6}]},{"kind":"snack","title":"بودنق التشوكلت","method":"المكونات:\n• بسكويت Galleta Zero (حوالي 158 كالوري)\n• 2 حبة أوريو (86 كالوري تقريباً)\n• 2غ بودرة كاكاو خام (حوالي 5 كالوري)\n• 25غ بياض بيض (13 كالوري تقريباً)\n• 18غ صفار بيض (58 كالوري تقريباً)\n• 40غ شوفان فوري (حوالي 154 كالوري)\n\nالطريقة:\n1. نطحن البسكويت مع حبتين الأوريو لين يصير فتات ناعم بوعاء يصلح للمايكرويف.\n2. نضيف الشوفان الفوري وبودرة الكاكاو للفتات ونخلطها زين لين تتوزع المكونات الجافة.\n3. نضيف بياض وصفار البيض ونخلط زين لين يصير الخليط متجانس. وممكن نضيف ملعقة أو ملعقتين ماء أو حليب قليل الدسم إذا صار سميك زيادة.\n4. نسكب الخليط بكوب أو طبق صغير يصلح للمايكرويف، ونترك فراغ بسيط لأن الخليط ينتفخ وقت التسوية.\n5. نطبخه بالمايكرويف 60–90 ثانية لين يتماسك السطح ويبقى الوسط طري شوي. الوقت يعتمد على قوة جهازك، ابدأ بـ 60 ثانية وزيّد تدريجياً إذا احتاج.\n\nملاحظة: القيم تقريبية: البروتين 16–17غ (اعتمدنا 16.5) والدهون 17–18غ (اعتمدنا 17.5).","items":[{"food":"بودنق التشوكلت","portion":"صحن","protein":16.5,"carbs":64,"fat":17.5}]},{"kind":"snack","title":"موس الشوكولاتة بالبروتين والأفوكادو","method":"المكونات:\n• نص حبة أفوكادو ناضجة\n• 1 سكوب بروتين شوكولاتة\n• 1 ملعقة صغيرة كاكاو بودرة غير محلّى\n• ربع كوب حليب لوز\n• 1 ملعقة صغيرة عسل أو ستيفيا\n\nالطريقة:\n1. نحط كل المكونات بالخلاط ونمزجها لين نحصل قوام كريمي ناعم.\n2. نقدّمه بكوب مع شوية رقائق شوكولاتة داكنة أو مكسرات مطحونة.\n3. نبرّده 15 دقيقة قبل ما ناكله عشان يصير قوامه مثالي.","items":[{"food":"موس الشوكولاتة بالبروتين والأفوكادو","portion":"كوب","protein":25,"carbs":15,"fat":13}]},{"kind":"snack","title":"بار البروتين بالمكسرات","method":"المكونات:\n• 55غ شوفان مطحون\n• سكوب ونص بروتين نكهة فانيلا أو شوكولاتة\n• 32غ زبدة فول سوداني\n• 20غ لوز أو جوز مطحون\n• 30غ عسل\n• 60مل حليب لوز غير محلّى\n• خلاصة فانيلا + رشة قرفة (اختياري)\n\nالطريقة:\n1. نمزج المكونات الجافة (الشوفان، البروتين، اللوز).\n2. بوعاء ثاني نخلط الزبدة والعسل وحليب اللوز لين يتجانسون.\n3. نضيف الجاف على الرطب ونمزج لين نحصل عجينة متماسكة.\n4. نفرد الخليط بصينية مبطّنة بورق زبدة ونضغطه زين.\n5. ندخله الثلاجة ساعة على الأقل.\n6. نقطّعه 5 ألواح متساوية.","items":[{"food":"بار البروتين بالمكسرات","portion":"بار","protein":18,"carbs":20,"fat":12}]},{"kind":"snack","title":"مافن البروتين بالموز والشوفان","method":"المكونات:\n• 1 كوب شوفان مطحون\n• 1 سكوب واي بروتين نكهة فانيلا\n• 1 موزة مهروسة\n• 2 بياض بيض\n• ربع كوب زبادي يوناني\n• 1 ملعقة صغيرة بيكنج باودر\n• نص ملعقة صغيرة قرفة\n• ربع كوب حليب لوز غير محلّى\n\nالطريقة:\n1. نسخّن الفرن على 180°م.\n2. نخلط كل المكونات بوعاء لين يصير الخليط متجانس.\n3. نسكب الخليط بقوالب مافن مبطّنة بورق زبدة.\n4. نخبزه 15–18 دقيقة لين يصير ذهبي.\n5. نتركه يبرد شوي قبل التقديم.","items":[{"food":"مافن البروتين بالموز والشوفان","portion":"مافن","protein":12,"carbs":20,"fat":2}]},{"kind":"snack","title":"بودينغ الشوكولاتة بالبروتين","method":"المكونات:\n• 1 سكوب واي بروتين نكهة شوكولاتة (30غ)\n• 240غ حليب خالي الدسم\n• 10غ شوكولاتة داكنة (70–85%)\n• 1 ملعقة صغيرة نشا الذرة (3غ)\n• 1 ملعقة صغيرة عسل (7غ)\n• ربع ملعقة صغيرة فانيلا\n\nالطريقة:\n1. بقدر صغير نذوّب نشا الذرة بشوية حليب بارد، ونضيف باقي الحليب والشوكولاتة والعسل.\n2. نطبخها على نار متوسطة مع التحريك المستمر لين تذوب الشوكولاتة ويصير القوام كثيف.\n3. نطفي النار ونتركها تبرد دقيقتين، وبعدها نضيف البروتين والفانيلا ونخفق زين.\n4. نسكبها بأكواب ونتركها ساعة بالثلاجة.\n\nالألياف: 1.1غ\n\nملاحظة: القيم محسوبة من المكونات بقاعدة بيانات USDA، والواي من ملف تغذية المدربة (سكوب = 25غ بروتين، 3 كارب، 2 دهون). نشا الذرة (3غ، حوالي 11 سعرة) غير محسوب. بدّلنا حليب اللوز والكاكاو بمكونات معروفة القيم.","items":[{"food":"بودينغ الشوكولاتة بالبروتين","portion":"كوب","protein":34,"carbs":25.4,"fat":6.5}]},{"kind":"snack","title":"وافل البروتين بالفانيلا","method":"المكونات:\n• 1 سكوب واي بروتين نكهة فانيلا\n• 130غ بياض بيض\n• 60مل حليب لوز غير محلّى\n• 30غ دقيق شوفان\n• نص ملعقة صغيرة بيكنج باودر\n• نص ملعقة صغيرة فانيلا\n• نص ملعقة صغيرة قرفة\n\nالطريقة:\n1. نسخّن آلة الوافل وندهنها بقليل زيت.\n2. نخلط كل المكونات بوعاء لين نحصل خليط سلس.\n3. نسكب الخليط بآلة الوافل ونطبخه لين يصير ذهبي ومقرمش.\n4. نقدّمه مع شوية زبدة لوز أو توت طازج.","items":[{"food":"وافل البروتين بالفانيلا","portion":"قطعة","protein":42.8,"carbs":24,"fat":4}]},{"kind":"breakfast","title":"بولة زبادي يوناني بالتوت والرمان والجوز","method":"المكونات:\n• 200غ زبادي يوناني خالي الدسم\n• 75غ توت أزرق\n• 40غ حبوب رمان\n• 15غ جوز (عين الجمل)\n• 10غ بذور الشيا\n\nالطريقة:\n1. نحط الزبادي بوعاء.\n2. نوزّع التوت وحبوب الرمان فوقه.\n3. نرش الجوز المفروم وبذور الشيا، ونقدّمه بارد.\n\nالألياف: 7.8غ","items":[{"food":"بولة زبادي يوناني بالتوت والرمان والجوز","portion":"وجبة كاملة","protein":25.5,"carbs":31.8,"fat":14.4}]},{"kind":"breakfast","title":"شكشوكة بالسبانخ والفلفل الأحمر","method":"المكونات:\n• 200غ طماطم مقطّعة\n• 60غ فلفل رومي أحمر\n• 50غ بصل\n• 60غ سبانخ\n• بيضتين (100غ)\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• رغيف عربي بر صغير (64غ)\n• ملح وفلفل أسود وكمون\n\nالطريقة:\n1. نسخّن زيت الزيتون بمقلاة ونقلّب البصل لين يذبل.\n2. نضيف الفلفل والطماطم ونطبخهم على نار متوسطة لين يصيرون مثل الصوص.\n3. نضيف السبانخ ونقلّب دقيقة لين تذبل.\n4. نسوي فجوتين بالصوص ونكسر فيهم البيض، ونغطي المقلاة ونطبخ لين يتماسك البياض.\n5. نقدّمها مع الخبز العربي.\n\nالألياف: 9.7غ\n\nملاحظة: القيم محسوبة من مكوناتها بقاعدة بيانات USDA. الأعشاب والتوابل وعصير الليمون غير محسوبة.","items":[{"food":"شكشوكة بالسبانخ والفلفل الأحمر","portion":"وجبة كاملة","protein":23.6,"carbs":54.7,"fat":16.5}]},{"kind":"breakfast","title":"شوفان بالفراولة والتوت والجوز","method":"المكونات:\n• 40غ شوفان\n• 200غ حليب خالي الدسم\n• 75غ فراولة مقطّعة\n• 50غ توت أزرق\n• 10غ جوز (عين الجمل)\n• 8غ بذور الشيا\n\nالطريقة:\n1. بقدر صغير نسخّن الحليب ونضيف الشوفان.\n2. نطبخه على نار هادية 5 دقايق لين يثقل.\n3. نسكبه بوعاء ونضيف الفراولة والتوت.\n4. نرش الجوز المفروم وبذور الشيا فوقه.\n\nالألياف: 10.2غ","items":[{"food":"شوفان بالفراولة والتوت والجوز","portion":"وجبة كاملة","protein":15.8,"carbs":54.8,"fat":12.2}]},{"kind":"lunch","title":"سلمون مشوي مع كينوا وسبانخ وطماطم","method":"المكونات:\n• 150غ سلمون (وزنه بعد الطبخ)\n• 120غ كينوا مطبوخة\n• 60غ سبانخ\n• 100غ طماطم\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• ملح وفلفل أسود وعصير ليمون\n\nالطريقة:\n1. نتبّل السلمون بالملح والفلفل والليمون ونشويه بالفرن أو بالمقلاة لين ينضج.\n2. نطبخ الكينوا بماء مملّح خفيف (جزء كينوا وجزئين ماء) لين تلين.\n3. بمقلاة نسخّن زيت الزيتون ونقلّب السبانخ والطماطم المقطّعة دقيقتين لين تذبل.\n4. نقدّم السلمون فوق الكينوا مع الخضار.\n\nالألياف: 5.9غ\n\nملاحظة: القيم محسوبة من مكوناتها بقاعدة بيانات USDA. الأعشاب والتوابل وعصير الليمون غير محسوبة.","items":[{"food":"سلمون مشوي مع كينوا وسبانخ وطماطم","portion":"وجبة كاملة","protein":41.1,"carbs":31.6,"fat":26.3}]},{"kind":"lunch","title":"سلطة عدس بالدجاج والخضار الملوّنة","method":"المكونات:\n• 150غ عدس مطبوخ\n• 120غ صدر دجاج مشوي ومقطّع\n• 60غ فلفل رومي أحمر\n• 80غ طماطم\n• 60غ خيار\n• 20غ بصل\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• عصير ليمون وبقدونس وملح وفلفل\n\nالطريقة:\n1. نقطّع الفلفل والطماطم والخيار والبصل مكعبات صغيرة.\n2. بوعاء كبير نخلط العدس مع الخضار وشرايح الدجاج.\n3. نتبّل بزيت الزيتون وعصير الليمون والبقدونس والملح والفلفل ونحرّك زين.\n4. نتركها 10 دقايق بالثلاجة عشان تتشرب النكهات.\n\nالألياف: 14.7غ\n\nملاحظة: القيم محسوبة من مكوناتها بقاعدة بيانات USDA. الأعشاب والتوابل وعصير الليمون غير محسوبة.","items":[{"food":"سلطة عدس بالدجاج والخضار الملوّنة","portion":"وجبة كاملة","protein":52.7,"carbs":40.9,"fat":10.3}]},{"kind":"lunch","title":"هامور بصلصة الطماطم والفلفل مع برغل","method":"المكونات:\n• 150غ هامور (وزنه بعد الطبخ)\n• 120غ برغل مطبوخ\n• 150غ طماطم\n• 60غ فلفل رومي أحمر\n• 50غ بصل\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• ثوم وكمون وملح وفلفل أسود\n\nالطريقة:\n1. نسخّن زيت الزيتون بمقلاة ونقلّب البصل والثوم لين يذبلون.\n2. نضيف الفلفل والطماطم والتوابل ونطبخهم على نار متوسطة 10 دقايق لين يصير صوص.\n3. نحط سمك الهامور بالصوص ونتركه على نار هادية لين ينضج.\n4. نقدّمه مع البرغل المطبوخ.\n\nالألياف: 9.3غ\n\nملاحظة: القيم محسوبة من مكوناتها بقاعدة بيانات USDA. الأعشاب والتوابل وعصير الليمون غير محسوبة.","items":[{"food":"هامور بصلصة الطماطم والفلفل مع برغل","portion":"وجبة كاملة","protein":43.4,"carbs":36.4,"fat":7.7}]},{"kind":"snack","title":"طبق توت وفراولة مع شوكولاتة داكنة ولوز","method":"المكونات:\n• 100غ توت أزرق\n• 100غ فراولة\n• 15غ شوكولاتة داكنة (70–85%)\n• 15غ لوز\n\nالطريقة:\n1. نغسل التوت والفراولة ونقطّع الفراولة.\n2. نحطهم بطبق ونكسّر الشوكولاتة الداكنة فوقهم.\n3. نضيف اللوز ونقدّمه.\n\nالألياف: 7.9غ","items":[{"food":"طبق توت وفراولة مع شوكولاتة داكنة ولوز","portion":"طبق","protein":5.8,"carbs":32.3,"fat":14.5}]},{"kind":"snack","title":"حمص بالخضار الملوّنة","method":"المكونات:\n• 60غ حمص بالطحينة\n• 60غ جزر\n• 60غ فلفل رومي أحمر\n• 60غ خيار\n\nالطريقة:\n1. نقطّع الجزر والفلفل والخيار أصابع.\n2. نحط الحمص بطبق صغير ونقدّم الخضار جنبه للغمس.\n\nالألياف: 6.5غ","items":[{"food":"حمص بالخضار الملوّنة","portion":"طبق